16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java((owner.getFirstName().charAt(0) + \".\" + owner.getLastName().charAt(0) + \".\").toUpperCase())")
24	    @Mapping(target = "householdId", expression = "java(org.springframework.samples.petclinic.service.HouseholdMatcher.householdId(owner))")
25	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.service.IdentityKey.of(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.service.CheckDigit.of(owner.getCustomerCode()))")
27	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
28	    @Mapping(target = "membershipLevel", expression = "java(Math.min(3, 1 + (owner.getEmail() != null && !owner.getEmail().isBlank() ? 1 : 0) + (Integer.valueOf(0).equals(owner.getNamesakeCount()) ? 1 : 0)))")
29	    @Mapping(target = "locality", expression = "java(owner.getCustomerCode().substring(0, owner.getCustomerCode().indexOf('-')))")
30	    @Mapping(target = "contactPreference", expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
31	    @Mapping(target = "ageBand", expression = "java(org.springframework.samples.petclinic.service.AgeBand.of(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    Owner toOwner(OwnerDto ownerDto);
35	
36	    @Mapping(target = "id", ignore = true)
37	    @Mapping(target = "pets", ignore = true)
38	    @Mapping(target = "telephone", qualifiedByName = "normalizeTelephone")
39	    @Mapping(target = "address", expression = "java(org.springframework.samples.petclinic.service.AddressNormalizer.normalize(ownerDto.getAddress()))")
40	    @Mapping(target = "postcode", expression = "java(org.springframework.samples.petclinic.service.PostcodeValidator.validate(ownerDto.getCity(), ownerDto.getPostcode()))")
41	    @Mapping(target = "registrationDate", expression = "java(org.springframework.samples.petclinic.service.RegistrationDateValidator.validate(ownerDto.getRegistrationDate()))")
42	    Owner toOwner(OwnerFieldsDto ownerDto);
43	
44	    /**
45	     * Normalise a telephone to E.164 for storage: keep an explicit leading '+' and country
46	     * code when present, otherwise assume '+61' and drop a single leading national '0'.
47	     * Spaces, dashes and brackets are stripped; the result must have 8 to 15 digits after
48	     * the '+', else the number is rejected as invalid.
49	     */
50	    @Named("normalizeTelephone")
51	    default String normalizeTelephone(String telephone) {
52	        if (telephone == null) {
53	            return null;
54	        }
55	        boolean international = telephone.trim().startsWith("+");
56	        String digits = telephone.replaceAll("\\D", "");
57	        if (!international) {
58	            if (digits.startsWith("0")) {
59	                digits = digits.substring(1);
60	            }
61	            digits = "61" + digits;
62	        }
63	        if (digits.length() < 8 || digits.length() > 15) {
64	            throw new IllegalArgumentException("Telephone cannot form a valid E.164 number: " + telephone);
65	        }
66	        org.springframework.samples.petclinic.service.E164NationalLength.check(digits);
67	        return "+" + digits;
68	    }
69	
70	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
71	
72	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
73	
74	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
75	        OwnerPageDto ownerPageDto = new OwnerPageDto();
76	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
77	        ownerPageDto.setPage(ownerPage.getNumber());
78	        ownerPageDto.setSize(ownerPage.getSize());
79	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
80	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
81	        return ownerPageDto;
82	    }
83	}
